const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function strategyPresentation(lang, common) {
 const t=content[lang];
 const offers=t.offers.map((a,i)=>`<article class="strategy-offer"><span class="mono">0${i+1} / STRATEGY</span><h3>${escape(a[0])}</h3><p>${escape(a[1])}</p><span class="mono">${t.receive}</span><p>${escape(a[2])}</p><p class="result">${escape(a[3])}</p></article>`).join('');
 const samples=t.samples.map(a=>`<figure class="strategy-sample"><figcaption>${escape(a[1])}</figcaption><h3>${escape(a[0])}</h3><dl><dt>${escape(a[2])}</dt><dd>${escape(a[3])}</dd><dt>${escape(a[4])}</dt><dd>${escape(a[5])}</dd></dl><p class="decision"><span class="mono">${escape(a[6])}</span><br>${escape(a[7])}</p></figure>`).join('');
 const frTitles=['Stratégie créative','Positionnement de marque','Conseil créatif','Stratégie de communication','Recherche sur les publics','Planification des contenus'];
 const services=common.services.map((a,i)=>`<article class="service"><span class="mono">0${i+1}</span><h2>${escape(lang==='fr'?frTitles[i]:a[0])}</h2><div><p>${escape(a[1])}</p><small>${common.deliver}</small><p class="deliver">${escape(a[2])}</p></div></article>`).join('');
 const needs=t.needs.map((a,i)=>`<li><span>0${i+1}</span>${escape(a)}</li>`).join('');
 const steps=t.steps.map((a,i)=>`<article><span class="mono">0${i+1}</span><h3>${escape(a[0])}</h3><p>${escape(a[1])}</p></article>`).join('');
 return `<main><section class="strategy-hero"><div class="wrap"><span class="mono kicker">${common.client} / 01 — STRATEGY</span><h1>${t.headline}</h1><p class="intro">${t.intro}</p><p class="lead">${t.lead}</p></div></section><section class="strategy-section"><h2>${t.needsTitle}</h2><ul class="strategy-needs">${needs}</ul></section><section class="strategy-section"><h2>${t.offersTitle}</h2><p>${t.offersLead}</p><div class="strategy-offers">${offers}</div></section><section class="strategy-examples"><div class="strategy-section"><h2>${t.examplesTitle}</h2><p>${t.examplesLead}</p><span class="mono">${t.sampleLabel}</span><p class="strategy-example-context">${t.exampleContext}</p><div class="strategy-samples">${samples}</div></div></section><section class="strategy-section strategy-catalog"><h2>${t.catalogTitle}</h2><p>${t.catalogLead}</p><div class="services">${services}</div></section><section class="strategy-section strategy-method"><h2>${t.methodTitle}</h2><div class="steps">${steps}</div><p class="note">${t.scope}</p></section><section class="strategy-cta"><div><h2>${t.cta}</h2><p>${t.ctaBody}</p><a href="mailto:contact@mazedproduction.com?subject=STRATEGY">${t.button} ↗</a></div></section></main><footer><span class="mono">©2023 MAZEDPRODUCTION. ALL RIGHTS RESERVED</span><form method="post" action="/strategy?lang=${lang}"><input type="hidden" name="action" value="logout"><button class="signout">${common.logout}</button></form></footer>`;
}
